('SKD', 'Surat Keterangan Domisili', '202', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "lainnya", "label": "Keperluan", "type": "fields", "fields": [{"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk dan berdomisili di Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}, sesuai alamat tersebut di atas.</p><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 10, now()),
('SKDO', 'Surat Keterangan Domisili Organisasi', '203', '{"layout": "keterangan", "sections": [{"key": "penanggung_jawab", "label": "Penanggung Jawab / Ketua", "type": "penduduk", "tampilkan": ["nama", "nik", "pekerjaan", "alamat"]}, {"key": "organisasi", "label": "Data Organisasi", "type": "fields", "fields": [{"key": "nama_organisasi", "label": "Nama organisasi/lembaga", "type": "text", "required": true, "register": true}, {"key": "bidang_organisasi", "label": "Bidang/jenis kegiatan", "type": "text"}, {"key": "alamat_organisasi", "label": "Alamat sekretariat", "type": "text", "required": true}, {"key": "akta_organisasi", "label": "Nomor akta/SK pendirian", "type": "text"}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p><table><tbody><tr><td style="width:50mm">Nama Organisasi</td><td>:</td><td>{{ nama_organisasi }}</td></tr><tr><td style="width:50mm">Bidang Kegiatan</td><td>:</td><td>{{ bidang_organisasi }}</td></tr><tr><td style="width:50mm">Nomor Akta/SK</td><td>:</td><td>{{ akta_organisasi }}</td></tr><tr><td style="width:50mm">Alamat Sekretariat</td><td>:</td><td>{{ alamat_organisasi }}</td></tr></tbody></table><p>benar berdomisili di Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}, dengan penanggung jawab:</p>{{ biodata(penanggung_jawab) }}<p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP Ketua", "wajib": 1}, {"nama": "Akta/SK Pendirian", "wajib": 0}]'::jsonb, 1, 11, now()),
('SKTM', 'Surat Keterangan Tidak Mampu', '204', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "lainnya", "label": "Keperluan", "type": "fields", "fields": [{"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p><p>Sepanjang sepengetahuan kami, orang tersebut di atas benar-benar berasal dari keluarga tidak mampu (kurang mampu) secara ekonomi.</p><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 12, now()),
('SKU', 'Surat Keterangan Usaha', '205', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "usaha", "label": "Data Usaha", "type": "fields", "fields": [{"key": "nama_usaha", "label": "Nama usaha", "type": "text"}, {"key": "jenis_usaha", "label": "Jenis usaha", "type": "text", "required": true, "register": true}, {"key": "alamat_usaha", "label": "Alamat/lokasi usaha", "type": "text", "required": true}, {"key": "mulai_usaha", "label": "Berdiri sejak (tahun)", "type": "text"}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p><p>Sepanjang sepengetahuan kami, orang tersebut di atas benar-benar mempunyai usaha sebagai berikut:</p><table><tbody><tr><td style="width:50mm">Nama Usaha</td><td>:</td><td>{{ nama_usaha }}</td></tr><tr><td style="width:50mm">Jenis Usaha</td><td>:</td><td>{{ jenis_usaha }}</td></tr><tr><td style="width:50mm">Alamat Usaha</td><td>:</td><td>{{ alamat_usaha }}</td></tr><tr><td style="width:50mm">Berdiri Sejak</td><td>:</td><td>{{ mulai_usaha }}</td></tr></tbody></table><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 13, now()),
('SREK', 'Surat Rekomendasi', '207', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "lainnya", "label": "Rekomendasi", "type": "fields", "fields": [{"key": "tujuan", "label": "Ditujukan kepada", "type": "text", "required": true, "register": true}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p><p>Pada prinsipnya kami tidak keberatan dan memberikan rekomendasi kepada orang tersebut di atas untuk keperluan {{ keperluan }} kepada {{ tujuan }}.</p><p>Demikian surat rekomendasi ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 14, now()),
('SKH', 'Surat Keterangan Kehilangan', '208', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "kehilangan", "label": "Data Kehilangan", "type": "fields", "fields": [{"key": "barang_hilang", "label": "Barang/dokumen yang hilang", "type": "textarea", "required": true, "register": true}, {"key": "tanggal_hilang", "label": "Tanggal kehilangan", "type": "date"}, {"key": "lokasi_hilang", "label": "Lokasi kehilangan", "type": "text"}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p><p>Menurut keterangan yang bersangkutan, telah kehilangan {{ barang_hilang }} pada tanggal {{ tgl_indo(tanggal_hilang) }} di {{ lokasi_hilang }}.</p><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 15, now()),
('SKTTS', 'Surat Keterangan Tanah Tidak Sengketa', '210', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "tanah", "label": "Data Tanah", "type": "fields", "fields": [{"key": "lokasi_tanah", "label": "Lokasi tanah", "type": "text", "required": true, "register": true}, {"key": "luas_tanah", "label": "Luas (m²)", "type": "number", "required": true}, {"key": "bukti_tanah", "label": "Bukti kepemilikan (SPPT/Pipil/Sertifikat) & nomor", "type": "text"}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}, {"key": "batas", "label": "Batas-batas Tanah", "type": "daftar", "columns": [{"key": "arah", "label": "Arah", "type": "select", "options": ["Utara", "Timur", "Selatan", "Barat"]}, {"key": "berbatasan", "label": "Berbatasan dengan", "type": "text"}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p><p>Orang tersebut di atas benar memiliki/menguasai sebidang tanah yang terletak di {{ lokasi_tanah }} seluas {{ luas_tanah }} m² dengan bukti kepemilikan {{ bukti_tanah }}, dengan batas-batas:</p>{{ tabel(batas) }}<p>Sepanjang sepengetahuan kami, tanah tersebut sampai saat ini tidak dalam sengketa dengan pihak mana pun.</p><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}, {"nama": "SPPT/Bukti kepemilikan tanah", "wajib": 1}]'::jsonb, 1, 16, now()),
('SKPOT', 'Surat Keterangan Penghasilan Orang Tua', '211', '{"layout": "keterangan", "sections": [{"key": "orang_tua", "label": "Data Orang Tua", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "pekerjaan", "alamat"]}, {"key": "anak", "label": "Data Anak", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl"]}, {"key": "lainnya", "label": "Penghasilan", "type": "fields", "fields": [{"key": "penghasilan", "label": "Penghasilan per bulan", "type": "rupiah", "required": true}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(orang_tua) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p><p>Orang tersebut di atas adalah orang tua dari:</p>{{ biodata(anak) }}<p>dan benar mempunyai penghasilan rata-rata sebesar {{ penghasilan }} ({{ terbilang(penghasilan, "rupiah") }}) per bulan.</p><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 17, now()),
('SKBM', 'Surat Keterangan Belum Menikah', '148.1', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "kewarganegaraan", "alamat"]}, {"key": "lainnya", "label": "Keperluan", "type": "fields", "fields": [{"key": "keperluan", "label": "Keperluan (salah satu syarat ...)", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p><p>Sejauh pengamatan dan penelitian yang kami lakukan, memang benar yang bersangkutan belum pernah sama sekali melangsungkan pernikahan sampai dengan saat ini.</p><p>Surat keterangan ini diberikan kepada yang bersangkutan sebagai salah satu syarat {{ keperluan }}.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 18, now()),
('SKET', 'Surat Keterangan', '470', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "jenis_kelamin", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "keterangan", "label": "Keterangan", "type": "teks_bebas", "required": true}, {"key": "lainnya", "label": "Keperluan", "type": "fields", "fields": [{"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Orang tersebut di atas benar-benar penduduk Desa {{ desa.nama }} Kecamatan {{ desa.kecamatan }} Kabupaten {{ desa.kabupaten }}.</p>{{ keterangan }}<p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 19, now()),
('SKL', 'Surat Keterangan Kelahiran', '470', '{"layout": "keterangan", "sections": [{"key": "ibu", "label": "Data Ibu", "type": "penduduk", "tampilkan": ["nik", "nama", "ttl", "alamat"]}, {"key": "ayah", "label": "Data Bapak", "type": "penduduk", "tampilkan": ["nik", "nama", "ttl", "alamat"]}, {"key": "anak", "label": "Data Anak", "type": "fields", "fields": [{"key": "nama_anak", "label": "Nama lengkap anak", "type": "text", "required": true, "register": true}, {"key": "anak_ke", "label": "Anak ke-", "type": "number"}, {"key": "jk_anak", "label": "Jenis kelamin", "type": "select", "required": true, "options": ["Laki-laki", "Perempuan"]}, {"key": "tempat_lahir_anak", "label": "Tempat lahir (kabupaten)", "type": "text", "required": true}, {"key": "tanggal_lahir_anak", "label": "Tanggal lahir", "type": "date", "required": true}, {"key": "alamat_anak", "label": "Alamat anak", "type": "text"}, {"key": "penolong", "label": "Penolong kelahiran", "type": "select", "options": ["Bidan", "Dokter", "Dukun Bayi"]}, {"key": "alamat_penolong", "label": "Alamat penolong", "type": "text"}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p><table><tbody><tr><td style="width:50mm">Nama Lengkap Anak</td><td>:</td><td><b>{{ nama_anak }}</b></td></tr><tr><td style="width:50mm">Anak Ke</td><td>:</td><td>{{ anak_ke }}</td></tr><tr><td style="width:50mm">Jenis Kelamin</td><td>:</td><td>{{ jk_anak }}</td></tr><tr><td style="width:50mm">Dilahirkan di</td><td>:</td><td>{{ tempat_lahir_anak }}, {{ tgl_indo(tanggal_lahir_anak) }}</td></tr><tr><td style="width:50mm">Alamat Anak</td><td>:</td><td>{{ alamat_anak }}</td></tr><tr><td style="width:50mm">Penolong Kelahiran</td><td>:</td><td>{{ penolong }}</td></tr><tr><td style="width:50mm">Alamat Penolong</td><td>:</td><td>{{ alamat_penolong }}</td></tr></tbody></table><p style="text-indent:0">Adalah anak kandung dari suami istri tersebut di bawah ini:</p><p style="text-indent:0"><b>IBU</b></p>{{ biodata(ibu) }}<p style="text-indent:0"><b>BAPAK</b></p>{{ biodata(ayah) }}<p>Surat keterangan ini dipergunakan untuk: Persyaratan pembuatan akta kelahiran.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP Orang Tua", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}, {"nama": "Surat Keterangan Lahir dari Bidan/RS", "wajib": 0}]'::jsonb, 1, 20, now()),
('SKK', 'Surat Keterangan Kematian', '470', '{"layout": "keterangan", "sections": [{"key": "almarhum", "label": "Data yang Meninggal", "type": "penduduk", "tampilkan": ["nama", "nik", "no_kk", "ttl", "jenis_kelamin", "kewarganegaraan", "agama", "status_perkawinan", "pekerjaan", "alamat"]}, {"key": "kematian", "label": "Data Kematian", "type": "fields", "fields": [{"key": "hari_meninggal", "label": "Hari", "type": "select", "options": ["Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"]}, {"key": "tanggal_meninggal", "label": "Tanggal meninggal", "type": "date", "required": true, "register": true}, {"key": "tempat_kematian", "label": "Tempat kematian", "type": "text", "required": true}, {"key": "sebab_kematian", "label": "Sebab kematian", "type": "text"}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(almarhum) }}<p style="text-indent:0">Telah meninggal dunia pada:</p><table><tbody><tr><td style="width:50mm">Hari / Tanggal</td><td>:</td><td>{{ hari_meninggal }}, {{ tgl_indo(tanggal_meninggal) }}</td></tr><tr><td style="width:50mm">Tempat Kematian</td><td>:</td><td>{{ tempat_kematian }}</td></tr><tr><td style="width:50mm">Sebab Kematian</td><td>:</td><td>{{ sebab_kematian }}</td></tr></tbody></table><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP Almarhum", "wajib": 0}, {"nama": "Kartu Keluarga", "wajib": 1}]'::jsonb, 1, 21, now()),
('SKBN', 'Surat Keterangan Beda Nama', '470', '{"layout": "keterangan", "sections": [{"key": "pemohon", "label": "Data Pemohon", "type": "penduduk", "tampilkan": ["nama", "nik", "ttl", "alamat"]}, {"key": "dokumen", "label": "Nama pada Dokumen", "type": "daftar", "columns": [{"key": "dokumen", "label": "Dokumen", "type": "text", "required": true}, {"key": "nomor", "label": "Nomor", "type": "text"}, {"key": "nama", "label": "Nama tertulis", "type": "text", "required": true}]}, {"key": "lainnya", "label": "Keterangan", "type": "fields", "fields": [{"key": "dokumen_acuan", "label": "Nama yang benar sesuai (KTP/KK/Ijazah/Akta)", "type": "text", "required": true}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ biodata(pemohon) }}<p>Berdasarkan dokumen-dokumen berikut:</p>{{ tabel(dokumen) }}<p>Nama-nama tersebut di atas adalah milik satu orang, yaitu nama yang tercantum dalam {{ dokumen_acuan }}.</p><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}, {"nama": "Dokumen yang berbeda nama", "wajib": 1}]'::jsonb, 1, 22, now()),
('SKAW', 'Surat Keterangan Ahli Waris', '470', '{"layout": "keterangan", "sections": [{"key": "pewaris", "label": "Data Pewaris (yang meninggal)", "type": "penduduk", "tampilkan": ["nama", "nik", "alamat"]}, {"key": "kematian", "label": "Kematian Pewaris", "type": "fields", "fields": [{"key": "tanggal_meninggal", "label": "Tanggal meninggal", "type": "date", "required": true}, {"key": "tempat_meninggal", "label": "Meninggal di (desa/kecamatan/kabupaten)", "type": "text"}, {"key": "keperluan", "label": "Keperluan", "type": "text", "required": true, "register": true}]}, {"key": "ahli_waris", "label": "Daftar Ahli Waris", "type": "daftar", "columns": [{"key": "nama", "label": "Nama", "type": "text", "required": true}, {"key": "ttl", "label": "Tempat/Tgl. Lahir", "type": "text"}, {"key": "nik", "label": "NIK", "type": "text"}, {"key": "pekerjaan", "label": "Pekerjaan", "type": "text"}, {"key": "alamat", "label": "Alamat", "type": "text"}, {"key": "hubungan", "label": "Hubungan", "type": "text"}]}]}'::jsonb, '<p style="text-indent:0">Yang bertanda tangan di bawah ini:</p><table><tbody><tr><td style="width:40mm">Nama</td><td>:</td><td>{{ ttd.nama }}</td></tr><tr><td>Jabatan</td><td>:</td><td>{{ ttd.jabatan }}</td></tr></tbody></table><p style="text-indent:0">dengan ini menerangkan bahwa:</p>{{ tabel(ahli_waris) }}<p>Berdasarkan sepengetahuan kami, orang-orang tersebut di atas adalah benar ahli waris dari almarhum/almarhumah <b>{{ pewaris.nama }}</b> yang telah meninggal pada tanggal {{ tgl_indo(tanggal_meninggal) }} di {{ tempat_meninggal }}.</p><p>Surat keterangan ini dipergunakan untuk keperluan: <b>"{{ keperluan }}"</b>.</p><p>Demikian surat keterangan ini dibuat untuk dipergunakan sebagaimana mestinya.</p>', '[{"nama": "KTP Ahli Waris", "wajib": 1}, {"nama": "Kartu Keluarga", "wajib": 1}, {"nama": "Surat Keterangan Kematian", "wajib": 1}]'::jsonb, 1, 23, now()),
