('SU', 'Surat Undangan', '005', '{"layout": "dinas", "sections": [{"key": "kepala_surat", "label": "Kepala Surat", "type": "fields", "fields": [{"key": "sifat", "label": "Sifat", "type": "select", "options": ["Biasa", "Penting", "Segera", "Rahasia"]}, {"key": "lampiran", "label": "Lampiran", "type": "text"}, {"key": "perihal", "label": "Perihal", "type": "text", "required": true, "register": true}, {"key": "kepada", "label": "Kepada Yth.", "type": "text", "required": true, "register": true}, {"key": "di_tempat", "label": "Di (tempat tujuan)", "type": "text"}, {"key": "tembusan", "label": "Tembusan (satu per baris)", "type": "textarea"}]}, {"key": "detail_acara", "label": "Acara", "type": "fields", "fields": [{"key": "hari", "label": "Hari", "type": "select", "required": true, "options": ["Senin", "Selasa", "Rabu", "Kamis", "Jumat", "Sabtu", "Minggu"]}, {"key": "tanggal_acara", "label": "Tanggal", "type": "date", "required": true}, {"key": "pukul", "label": "Pukul", "type": "text", "required": true}, {"key": "tempat_acara", "label": "Tempat", "type": "text", "required": true}, {"key": "acara", "label": "Acara", "type": "textarea", "required": true, "register": true}]}]}'::jsonb, '<p>Dengan hormat,</p><p>Mengharap kehadiran Bapak/Ibu/Saudara pada:</p><table><tbody><tr><td style="width:50mm">Hari</td><td>:</td><td>{{ hari }}</td></tr><tr><td style="width:50mm">Tanggal</td><td>:</td><td>{{ tgl_indo(tanggal_acara) }}</td></tr><tr><td style="width:50mm">Pukul</td><td>:</td><td>{{ pukul }}</td></tr><tr><td style="width:50mm">Tempat</td><td>:</td><td>{{ tempat_acara }}</td></tr><tr><td style="width:50mm">Acara</td><td>:</td><td>{{ acara }}</td></tr></tbody></table><p>Mengingat pentingnya acara tersebut, dimohon hadir tepat waktu. Atas perhatian dan kehadirannya diucapkan terima kasih.</p>', '[]'::jsonb, 1, 25, now())
